package com.example.webapptemplate.janken;
import com.example.webapptemplate.platform.UserReferences;import java.util.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;
@Repository public class JankenReferences implements UserReferences {private final JdbcClient db;public JankenReferences(JdbcClient db){this.db=db;}public long count(UUID user){return db.sql("select (select count(*) from janken_rounds where user_id=:id)+(select count(*) from janken_lines where user_id=:id)").param("id",user).query(Long.class).single();}public Map<UUID,Long> counts(){var result=new HashMap<UUID,Long>();db.sql("select user_id,count(*) from (select user_id from janken_rounds union all select user_id from janken_lines) refs group by user_id").query((r,n)->{result.put(r.getObject(1,UUID.class),r.getLong(2));return 1;}).list();return result;}}
